function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,2600)}
function header(title,eyebrow='',cls=''){return `<header class="app-header"><div>${eyebrow?`<span class="eyebrow">${eyebrow}</span>`:''}<h2 class="${cls}">${title}</h2></div><button class="icon-btn" data-action="settings" aria-label="Assistant settings">${icon('settings')}</button></header>`}
