const ghostSpot={bath:{rest:[85,73,11,15],aim:[49.5,26,9,12]},closet:{rest:[74,60,15,17],aim:[46,26,16,22]},vanity:{rest:[80,62,11,14],aim:[57,39,9,12]}};
const dogLine={bath:'You have body wash. And its understudy.',closet:'Your next outfit is probably already in here.',vanity:'A routine is not a waiting list.'};
let roomDir=1,swipeHinted=false,squeezeRun=0;
function roomFull(){return spaceItems().length>=SPOTS}
function roomScene(){
 const items=spaceItems(),pos=roomSpots[room],g=ghost&&product(ghost).room===room,full=items.length>=SPOTS,gs=ghostSpot[room];
 const plan=g?state.plans.filter(p=>p.id===ghost).at(-1):null;
 let ghostHtml='';
 if(g){const [l,t,w,h]=gs.rest,[al,at]=gs.aim,fx=((al-l)/w*100).toFixed(1),fy=((at-t)/h*100).toFixed(1);
  ghostHtml=`<button class="room-item ghost ${full?'squeeze':'settle'}" style="left:${l}%;top:${t}%;width:${w}%;height:${h}%;--fx:${fx}%;--fy:${fy}%" data-action="ghost" aria-label="Wishlist preview, not owned. Tap to try again.">${art(product(ghost),plan?.size||'full')}<span>Just visiting</span></button>`}
 const pose=g?(full?'think':'peek'):room==='bath'?'sit':room==='closet'?'sleep':'think';
 const line=g?(full?'Shelf’s full. Even the backup has a backup.':'Room for one more. Is it a keeper?'):dogLine[room];
 const hint=!swipeHinted?'<span class="swipe-hint" aria-hidden="true">‹ swipe ›</span>':'';swipeHinted=true;
 return `<div class="room-scene room-${room}${g?' has-ghost':''}${g&&full?' is-full':''}" id="room-swipe" style="--enter:${roomDir}" aria-label="${roomName(room)}. Swipe left or right to switch rooms.">${roomDrawing()}${items.slice(0,SPOTS).map((p,i)=>{const [l,t,w,h]=pos[i];return `<button class="room-item${g&&full&&i<3?' jostle':''}" data-action="inventory" data-id="${p.id}" style="left:${l}%;top:${t}%;width:${w}%;height:${h}%;--d:${i*40}ms" aria-label="Inspect ${esc(p.name)}">${art(p)}<span class="item-tip">${esc(p.name)}</span></button>`}).join('')}${ghostHtml}<button class="scene-cat pose-${pose}" data-action="chat" data-id="${g?ghost:room==='closet'?'tee':'wash'}" aria-label="Talk to Momo">${cat(pose)}</button><button class="dog-bubble${g?' alert':''}" data-action="chat" data-id="${g?ghost:room==='closet'?'tee':'wash'}">${line}</button>${hint}</div>`
}
function ghostPanel(){const p=product(ghost),full=roomFull(),n=spaceItems().length;
 return `<div class="ghost-panel"><span class="eyebrow">WISHLIST PREVIEW · NOT OWNED</span><strong>${full?'No room on the shelf.':'It could fit in here.'}</strong><p>${full?`${n} things already live in your ${roomName(room).toLowerCase()}. The new ${p.name.toLowerCase()} is waiting on the floor.`:`${n} things live here. A maybe is not a must.`}</p><div class="action-row">${p.miniVolume?`<button class="primary" data-action="compare-mini" data-id="${p.id}">Try the mini</button>`:`<button class="primary" data-action="outfit" data-id="${p.id}">Style it with mine</button>`}<button class="secondary" data-action="clear-ghost">Leave it on my wishlist</button></div></div>`}
function homeView(){const items=spaceItems(),full=items.length>=SPOTS,g=ghost&&product(ghost).room===room;return `${header('Your home.','','serif-title')}<div class="room-tabs" role="tablist" aria-label="Your rooms">${rooms.map(([id,n])=>`<button role="tab" aria-selected="${room===id}" data-action="room" data-id="${id}" class="${room===id?'active':''}">${n}</button>`).join('')}</div>${roomScene()}${g?ghostPanel():`<div class="room-status"><div><strong>${items.length} items · ${full?'Shelf full':`${SPOTS-items.length} spot${SPOTS-items.length>1?'s':''} free`}</strong><div class="spot-dots" aria-hidden="true">${Array.from({length:SPOTS},(_,i)=>`<i class="${i<items.length?'on':''}"></i>`).join('')}</div></div><div class="room-tools"><button class="icon-btn" data-action="inventory-list" aria-label="See all ${items.length} items">${icon('list')}</button><button class="icon-btn" data-action="album" aria-label="Add an item">${icon('plus')}</button></div></div><button class="primary ask-momo" data-action="${room==='closet'?'outfit':'chat'}" data-id="${room==='closet'?'tee':'wash'}">${room==='closet'?`${icon('hanger')} Build an outfit`:`<span class="btn-dog">${cat()}</span> Ask Momo`}</button>`}`}
function changeRoom(delta){roomDir=delta<0?-1:1;room=rooms[(rooms.findIndex(r=>r[0]===room)+delta+3)%3][0];render(false)}
function bindSwipe(){const el=$('#room-swipe');if(!el)return;let x,y;el.addEventListener('pointerdown',e=>{x=e.clientX;y=e.clientY});el.addEventListener('pointerup',e=>{if(x===undefined)return;let dx=e.clientX-x,dy=e.clientY-y;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.5){changeRoom(dx<0?1:-1)}x=undefined});}
// Show a room only when its drawing and the product art are ready, so nothing floats on a blank page.
const artFiles=['bathroom','wardrobe','vanity','dog-four-poses','girl-three-poses','care-products','wardrobe-products','almond-body-wash-100ml','care-products-cutout','wardrobe-products-cutout','almond-body-wash-100ml-cutout'];
const artReady=Promise.all(artFiles.map(f=>{const i=new Image();i.src='assets/artwork/'+f+'.webp';return i.decode().catch(()=>{})})).then(()=>document.body.classList.add('assets-ready'));
function prepRoom(){const sc=$('#room-swipe');if(!sc)return;const img=sc.querySelector('.room-lines');const loaded=img.complete&&img.naturalWidth?Promise.resolve():new Promise(r=>{img.addEventListener('load',r,{once:true});img.addEventListener('error',r,{once:true})});Promise.all([loaded,artReady]).then(()=>requestAnimationFrame(()=>sc.classList.add('ready')))}
function card(p){return `<article class="product-card"><button class="product-picture" data-action="product" data-id="${p.id}" aria-label="View ${p.name}">${art(p)}</button><button class="heart-btn ${wishHas(p.id)?'on':''}" data-action="wish-toggle" data-id="${p.id}" aria-label="${wishHas(p.id)?'Remove':'Save'} ${p.name}">${icon('heart')}</button><span class="eyebrow">${p.brand}</span><h3>${p.name}</h3><div class="price">${money(p.price)} <del>${money(p.old)}</del></div></article>`}
function shopView(){const shown=products.filter(p=>(category==='All'||p.category===category)&&`${p.name} ${p.brand} ${p.category}`.toLowerCase().includes(query.toLowerCase()));return `${header('Finds')}<label class="search-box">${icon('search')}<input id="search" placeholder="What caught your eye?" aria-label="Search sample items" value="${esc(query)}"></label><div class="chips">${['All','Body & hair','Wardrobe','Skincare','Fragrance'].map(c=>`<button data-action="category" data-id="${c}" class="${category===c?'active':''}">${c}</button>`).join('')}</div><div class="product-grid">${shown.map(card).join('')}</div>${shown.length?'':'<p class="empty">No matches. Try “body wash” or “knit”.</p>'}<p class="footnote">Original sample products · Demo prices</p>`}
const stores=[{name:'Brand website',mark:'S',discount:.1,shipping:5,memberDiscount:.05},{name:'Sephora',mark:'S',discount:.05,shipping:6,memberDiscount:.15},{name:'Ulta Beauty',mark:'u',discount:.15,shipping:5.95,memberDiscount:.05},{name:'Amazon',mark:'a',discount:.08,shipping:6.99,memberDiscount:0},{name:'Walmart',mark:'W',discount:.12,shipping:6.99,memberDiscount:0}];
function storeLogo(name){const file={'Sephora':'sephora','Ulta Beauty':'ulta','Amazon':'amazon','Walmart':'walmart','Nordstrom':'nordstrom','Target':'target'}[name];return file?`<span class="store-logo"><img src="assets/logos/${file}.ico" alt="${name} logo"></span>`:`<span class="store-logo brand-store" aria-label="Brand website">${icon('bag')}</span>`}
function offers(){const p=product(compId),base=size==='mini'?+(p.price*.44).toFixed(2):p.price;return stores.map((s,i)=>{const discount=s.discount+(state.settings.member?s.memberDiscount:0),price=+(base*(1-discount)).toFixed(2),shipping=state.settings.member&&(i===1||i===3)?0:s.shipping;return {...s,name:p.category==='Wardrobe'?(i===1?'Nordstrom':i===2?'Target':s.name):s.name,index:i,discount,price,shipping,total:+(price+shipping).toFixed(2)}}).sort((a,b)=>a.total-b.total)}
function sizeLabel(p=product(compId),s=size){return p.category==='Wardrobe'?'Standard':`${s==='mini'?p.miniVolume:p.volume} ml`}
function compareView(){const p=product(compId),rows=offers(),best=rows[0];return `${header('Compare prices')}<div class="small-product">${art(p,size)}<div><span class="eyebrow">${p.brand}</span><h3>${p.name}</h3><p>${sizeLabel(p)} · 5 stores</p></div><button class="text-link" data-action="pick-product">Change</button></div>${p.volume?`<div class="segmented"><button data-action="size" data-id="full" class="${size==='full'?'active':''}">Full size · ${p.volume} ml</button><button data-action="size" data-id="mini" class="${size==='mini'?'active':''}">Mini size · ${p.miniVolume} ml</button></div>`:''}<div class="toggle-row"><span>Apply member perks <small>Demo eligibility</small></span><button class="switch ${state.settings.member?'on':''}" role="switch" aria-checked="${state.settings.member}" aria-label="Apply member perks" data-action="member"></button></div><div class="comparison-heading"><span>STORE</span><span>TOTAL BEFORE TAX</span></div>${rows.map((s,i)=>`<div class="store-card ${i===0?'best':''}"><button class="store-main" data-action="store" data-id="${s.index}" aria-expanded="${expandedStore===String(s.index)}">${storeLogo(s.name)}<div><strong>${s.name}</strong><small>${i===0?'LOWEST OF THESE FIVE':`${Math.round(s.discount*100)}% demo discount`}</small></div><span class="store-cost">${money(s.total)}<small>Details ⌄</small></span></button>${expandedStore===String(s.index)?`<div class="store-breakdown"><p><span>Item after discount</span><b>${money(s.price)}</b></p><p><span>Shipping</span><b>${money(s.shipping)}</b></p>${p.volume?`<p><span>Item price / 100 ml</span><b>${money(s.price/(size==='mini'?p.miniVolume:p.volume)*100)}</b></p>`:''}<p><span>Sales tax</span><span>Not included</span></p><small>${state.settings.member?'Assumes eligible membership.':'No member-only discount applied.'} Fictional offer.</small><button class="text-link" data-action="save-store" data-id="${s.index}">Save this plan ↗</button></div>`:''}</div>`).join('')}<p class="notice">Sample offers, not live prices. Includes example shipping; excludes tax. Membership conditions must be checked.</p><button class="primary" data-action="save-best">Save ${best.name} · ${money(best.total)} ${icon('arrow')}</button><button class="inline-note" data-action="chat" data-id="${p.id}">${cat()}<span>${size==='mini'?'New scent, smaller commitment. Love that for you.':'A deal is only a deal if you’ll use it.'}</span></button>`}
function compare(id,s='full'){compId=id||compId;size=product(compId).volume?s:'full';expandedStore='';navigate('compare')}
function saveOffer(index){const s=offers().find(s=>s.index===Number(index)),p=product(compId);if(!s)return;state.plans=state.plans.filter(x=>!(x.id===p.id&&x.size===size));state.plans.push({id:p.id,size,sizeLabel:sizeLabel(p),store:s.name,total:s.total,price:s.price,shipping:s.shipping,member:state.settings.member});if(!wishHas(p.id))state.wish.push({id:p.id,reason:size==='mini'?'Try a new scent':''});persist();toast('Plan saved. Zero actual checkout.');render(false)}
function wishHas(id){return state.wish.some(w=>w.id===id)}
function wishTotal(){return state.wish.reduce((sum,w)=>sum+(state.plans.filter(p=>p.id===w.id).at(-1)?.price??product(w.id).price),0)}
function wishView(){const total=wishTotal(),budget=state.settings.budget;return `${header('Wishlist')}<div class="budget-card"><div><span class="eyebrow">YOUR LITTLE-TREAT BUDGET</span><p><b>${money(total)}</b><span> / ${money(budget)}</span></p></div><button class="icon-btn" data-action="settings" aria-label="Edit budget">${icon('settings')}</button><div class="budget-track"><i style="width:${Math.min(100,total/budget*100)}%"></i></div><small>${total>budget?`${money(total-budget)} over. Let’s give your favorites a ranking.`:`${money(budget-total)} left. No need to spend it just because it’s there.`}<br>Item prices only. Shipping and tax excluded.</small></div>${state.wish.length?state.wish.map(w=>{const p=product(w.id),saved=state.plans.filter(x=>x.id===w.id).at(-1);return `<article class="wish-card"><button data-action="product" data-id="${p.id}" class="wish-art">${art(p,saved?.size||'full')}</button><div><span class="eyebrow">${p.brand}</span><h3>${p.name}</h3><b>${money(saved?.price??p.price)}</b><small class="wish-size">${sizeLabel(p,saved?.size||'full')}${saved?' · saved item price':' · sample item price'}</small><p>${esc(w.reason||'Still in the “just looking” era.')}</p><div class="wish-actions"><button data-action="compare" data-id="${p.id}">Compare</button><button data-action="preview" data-id="${p.id}">Room preview</button><button data-action="purchased" data-id="${p.id}">Got it</button></div></div><button class="remove" data-action="wish-toggle" data-id="${p.id}" aria-label="Remove ${p.name}">×</button></article>`}).join(''):`<div class="empty-state"><div class="empty-bag">${icon('bag')}</div><h3>Empty bag. Full potential.</h3><p>This is a wishlist, not a deadline.</p><button class="secondary" data-action="nav" data-id="shop">Find a little treat ↗</button></div>`}<button class="text-link" data-action="nav" data-id="shop">＋ Browse sample finds</button>${state.plans.length?'<h3 class="section-title">Plans, not purchases.</h3>'+state.plans.map((p,i)=>`<div class="saved-plan"><span class="eyebrow">${p.store} · ${sizeLabel(product(p.id),p.size)}</span><strong>${product(p.id).name}</strong><p>${money(p.total)} before tax <small>(${money(p.price)} + ${money(p.shipping)} shipping)</small></p><div><button data-action="plan-compare" data-id="${i}">Revisit ↗</button><button data-action="delete-plan" data-id="${i}">Remove</button></div></div>`).join(''):''}${state.outfits.length?`<button class="saved-outfit" data-action="outfit">${icon('hanger')} ${state.outfits.length} saved outfit${state.outfits.length>1?'s':''} · See latest ↗</button>`:''}`}
function showSheet(html,label){$('#overlay').innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(label)}"><div class="sheet-handle"></div><button class="sheet-close" data-action="close-sheet" aria-label="Close">×</button>${html}</section>`;$('#overlay').hidden=false;$('#nudge').hidden=true;$('#buddy-fab').hidden=true;$('#overlay button:not(.sheet-close)')?.focus({preventScroll:true})}
function closeSheet(){$('#overlay').hidden=true;$('#overlay').innerHTML='';$('#buddy-fab').hidden=!$('#chat').hidden}
function closeChat(){$('#chat').hidden=true;$('#app').inert=false;$('#nav').inert=false;$('#buddy-fab').hidden=!$('#overlay').hidden}
function detail(id){const p=product(id);showSheet(`<div class="detail-art">${art(p)}</div><span class="eyebrow">${p.brand}</span><h2>${p.name}</h2><p>${p.note}</p><div class="detail-price">${money(p.price)} <del>${money(p.old)}</del><small>${sizeLabel(p,'full')} · Demo price</small></div><button class="inline-note" data-action="chat" data-id="${id}">${cat()}<span>${id==='wash'?'Your 1-liter bottle would like a word. Refill, or new-scent crush?':id==='tee'?'Meet its cousin: the oatmeal knit you already own.':'You bring the taste. I bring the second thought.'}</span></button><div class="action-row"><button class="secondary" data-action="detail-wish" data-id="${id}">${icon('heart')} ${wishHas(id)?'Saved':'Save for later'}</button><button class="primary" data-action="compare" data-id="${id}">Compare 5 stores</button></div><button class="text-link full" data-action="${p.room==='closet'?'outfit':'preview'}" data-id="${id}">${p.room==='closet'?'Style it with what I own':'See it in my room'} ↗</button>`,p.name)}
function toggleWish(id,force=false){if(wishHas(id)){if(force){toast('Already in your maybe bag.');return}state.wish=state.wish.filter(w=>w.id!==id);toast('Removed. Room for another thought.')}else{state.wish.push({id,reason:''});addCount++;toast('Saved. A crush, not a commitment.');if(state.settings.frequency==='smart'&&(Date.now()-lastNudge>9000||addCount===3)){lastNudge=Date.now();setTimeout(()=>nudge(id),350)}}persist();render(false)}
function flyToBag(id,from){const target=$('#nav [data-id="wish"]');if(!target||!from||matchMedia('(prefers-reduced-motion: reduce)').matches){target?.classList.add('bump');return}const t=target.getBoundingClientRect(),size=Math.min(96,Math.max(56,from.width*.6)),x=from.left+from.width/2-size/2,y=from.top+from.height/2-size/2,el=document.createElement('div');el.className='fly-thumb';el.style.cssText=`left:${x}px;top:${y}px;width:${size}px;height:${size}px`;el.innerHTML=art(product(id));document.body.appendChild(el);const dx=t.left+t.width/2-(x+size/2),dy=t.top+t.height/2-(y+size/2);el.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dx*.55}px,${dy*.25-60}px) scale(.75) rotate(-8deg)`,opacity:1,offset:.45},{transform:`translate(${dx}px,${dy}px) scale(.18) rotate(6deg)`,opacity:.4}],{duration:720,easing:'cubic-bezier(.45,0,.2,1)'}).onfinish=()=>{el.remove();const nt=$('#nav [data-id="wish"]');nt?.classList.remove('bump');void nt?.offsetWidth;nt?.classList.add('bump')}}
function nudge(id){if(state.settings.frequency==='quiet'||!$('#overlay').hidden||!$('#chat').hidden)return;chatProduct=id;const text=state.settings.tone==='gentle'?'Want to check your shelf and budget together?':state.settings.tone==='concise'?'Saved. Review existing stock and budget before buying.':addCount>=3?'This wishlist is entering its shopping-cart era. Shall we prioritize?':id==='wash'?'Your backup body wash has a backup. Is this about the scent?':'Cute. Now let’s see if your space and budget agree.';{const m=$('.nav-momo');m?.classList.remove('perk');void m?.offsetWidth;m?.classList.add('perk')}$('#nudge').innerHTML=`<button class="nudge-close" data-action="close-nudge" aria-label="Dismiss reminder">×</button><span class="eyebrow">MOMO HAS A THOUGHT</span><p>${text}</p><button class="text-link" data-action="chat" data-id="${id}">Okay, hear me out →</button>`;$('#nudge').hidden=false}
function inventoryDetail(id){const p=owned(id);if(!p)return;showSheet(`<div class="detail-art owned-art">${art(p)}</div><span class="eyebrow">ALREADY YOURS. STILL GOOD.</span><h2>${esc(p.name)}</h2><p>${p.date?'Added '+esc(p.date):'Purchase date not recorded'}${p.volume?' · '+p.volume+' ml':''}</p>${p.room==='closet'?`<button class="primary" data-action="outfit" data-id="${id}">Put an outfit together ${icon('hanger')}</button>`:`<label for="remaining-range">How much is left? <strong id="remaining-value">${p.remaining<0?'Not sure':p.remaining+'%'}</strong></label><input id="remaining-range" type="range" min="0" max="100" value="${Math.max(p.remaining,0)}"><p class="footnote">Your estimate. A photo can’t tell us the actual amount.</p><button class="primary" data-action="remaining-save" data-id="${id}">Update amount</button><button class="text-link full" data-action="used-up" data-id="${id}">Finished it. Make some room.</button>`}<label for="move-room">Where does it live?</label><select id="move-room">${rooms.map(([v,n])=>`<option value="${v}" ${p.room===v?'selected':''}>${n}</option>`).join('')}</select><button class="text-link" data-action="move-item" data-id="${id}">Move item →</button>`,p.name)}
function inventoryList(){showSheet(`<span class="eyebrow">${roomName(room).toUpperCase()} INVENTORY</span><h2>Here’s the shelf situation.</h2><p>${spaceItems().length} items · 6 display spots. Extra items stay in your overflow list.</p><div class="inventory-list">${spaceItems().map(p=>`<button data-action="inventory" data-id="${p.id}">${art(p)}<span><strong>${esc(p.name)}</strong><small>${p.room==='closet'?'In your wardrobe':p.remaining<0?'Amount unknown':p.remaining+'% left'}</small></span>${icon('arrow')}</button>`).join('')}</div>`,'Room inventory')}
function settings(){showSheet(`<span class="eyebrow">YOUR SIDEKICK, YOUR RULES</span><h2>Set the Momo mood.</h2><p>A little perspective. At your preferred volume.</p><label>Personality</label><div class="segmented">${[['friend','Witty friend'],['gentle','Gentle nudge'],['concise','Just facts']].map(([v,n])=>`<button data-action="tone" data-id="${v}" class="${state.settings.tone===v?'active':''}">${n}</button>`).join('')}</div><p class="setting-example">${{friend:'“The sale ends tonight. Your shampoo does not.”',gentle:'“Love a new scent. Shall we try a smaller bottle first?”',concise:'“Check remaining stock, then compare total cost.”'}[state.settings.tone]}</p><label>When should I chime in?</label><div class="segmented">${[['smart','A timely nudge'],['quiet','Only when asked']].map(([v,n])=>`<button data-action="frequency" data-id="${v}" class="${state.settings.frequency===v?'active':''}">${n}</button>`).join('')}</div><label for="budget-field">Little-treat budget · USD</label><div class="inline-field"><input id="budget-field" type="number" min="1" max="100000" value="${state.settings.budget}"><button class="primary" data-action="budget-save">Save</button></div><details class="prototype-info"><summary>About this prototype</summary><p>Momo connects to Gemini on the Vercel app. Welcome messages and optional scripted demo replies are labeled. Sample products and prices; no real purchases or price monitoring. Chat text and relevant shelf records are sent through Vercel to Google. Photos stay in this browser.</p><p>Only photos you choose are used. No whole-album access, image recognition, or remote photo upload. Outfit previews are illustrative, not fit predictions.</p></details><button class="text-link" data-action="reset-confirm">Reset demo data ↺</button>`,'Assistant settings')}
function album(){selection=new Set();photoDraft=null;showSheet(`<span class="eyebrow">BRING YOUR THINGS HOME</span><h2>Less guessing. More knowing.</h2><div class="album-intro">${cropArt('girl-three-poses',[626,229,610,636],[1774,887],'organizing-girl')}<p>Choose an item photo, then tell Momo where it belongs.</p></div><button class="secondary" data-action="upload">${icon('camera')} Choose a photo</button><input type="file" accept="image/*" id="photo-file" hidden><p class="footnote">One photo you select. No access to your whole album.</p><h3 class="section-title">Or try the sample album</h3><div class="sample-grid">${products.slice(1).map(p=>`<button class="sample-card" data-action="sample-select" data-id="${p.id}" aria-pressed="false">${art(p)}<span>${p.name}</span><i>✓</i></button>`).join('')}</div><p class="footnote">Samples are pre-labeled. You confirm the details.</p><button id="album-next" class="primary" data-action="album-next" disabled>Choose an item to continue</button>`,'Add items')}
function confirmAlbum(){showSheet(`<span class="eyebrow">YOU KNOW YOUR THINGS BEST</span><h2>A quick shelf check.</h2>${photoDraft?`<img class="upload-preview" src="${photoDraft}" alt="Your selected item"><label for="upload-name">What is it?</label><input id="upload-name" placeholder="e.g. White cotton shirt" maxlength="45">`:`<p>${[...selection].map(id=>product(id).name).join(', ')}</p>`}<label for="album-room">Where does it belong?</label><select id="album-room">${rooms.map(([id,n])=>`<option value="${id}" ${room===id?'selected':''}>${n}</option>`).join('')}</select><label for="album-remain">How much is left?</label><select id="album-remain"><option value="-1">Not sure yet</option><option value="100">Brand new · 100%</option><option value="75">About 75%</option><option value="50">About half</option><option value="25">Almost finished · 25%</option></select><label for="album-date">Bought on (optional)</label><input id="album-date" type="date"><p class="footnote">A photo isn’t proof of how much is left. Your estimate is what counts.</p><p id="album-error" class="error"></p><button class="primary" data-action="album-save">Make it feel at home ${icon('arrow')}</button>`,'Confirm items')}
function saveAlbum(){const r=$('#album-room').value,remaining=Number($('#album-remain').value),date=$('#album-date').value;const picks=photoDraft?[{name:$('#upload-name').value.trim(),type:'bottle',photo:photoDraft}]:[...selection].map(product);if(!picks.length)return;if(photoDraft&&!picks[0].name){$('#album-error').textContent='Give this item a name first.';return}picks.forEach((p,i)=>state.inventory.push({...p,id:'custom-'+Date.now()+'-'+i,room:r,remaining:r==='closet'?100:remaining,date}));persist();room=r;navigate('home');toast(`${picks.length} item${picks.length>1?'s':''} moved in.`)}
function outfitArt(id){return owned(id)||product(id)}
function mannequin(){return cropArt('girl-three-poses',[1280,12,343,867],[1774,887],'mannequin')}
function outfitView(){const pieces=[...state.inventory.filter(p=>p.room==='closet'),...products.filter(p=>p.room==='closet')];showSheet(`<span class="eyebrow">SHOP YOUR OWN WARDROBE</span><h2>The outfit is already here.</h2><div class="segmented"><button data-action="outfit-mode" data-id="person" class="${outfitMode==='person'?'active':''}">On a sketch</button><button data-action="outfit-mode" data-id="board" class="${outfitMode==='board'?'active':''}">Style board</button><button data-action="outfit-mode" data-id="flat" class="${outfitMode==='flat'?'active':''}">Flat lay</button></div><div id="outfit-board" class="outfit-board ${outfitMode}">${outfitMode!=='flat'?mannequin():''}${Object.entries(outfit).map(([slot,id])=>`<div class="outfit-piece ${slot} type-${outfitArt(id).type}" data-slot="${slot}" ${outfitMode==='flat'?'tabindex="0" role="button"':''} aria-label="${esc(outfitArt(id).name)}${outfitMode==='flat'?', drag or use arrow keys to move':''}" style="${outfitMode==='flat'&&outfitPositions[slot]?`left:${outfitPositions[slot].left}px;top:${outfitPositions[slot].top}px`:''}">${art(outfitArt(id))}</div>`).join('')}<span class="board-caption">${outfitMode==='flat'?'DRAG THE PIECES. MAKE IT YOURS.':'YOUR NEXT LOOK. ALREADY IN YOUR CLOSET.'}</span></div><p class="footnote">Illustrative styling, not a fit prediction. Tap a piece to swap it, or arrange a flat lay.</p><div class="outfit-strip">${pieces.map(p=>`<button data-action="outfit-pick" data-id="${p.id}" class="${Object.values(outfit).includes(p.id)?'active':''}">${art(p)}<small>${esc(p.name)}</small></button>`).join('')}</div><button class="primary" data-action="outfit-save">Save this look ${icon('heart')}</button>`,'Outfit studio');if(outfitMode==='flat')enableDrag()}
function enableDrag(){document.querySelectorAll('.outfit-piece').forEach(el=>{const save=()=>outfitPositions[el.dataset.slot]={left:el.offsetLeft,top:el.offsetTop};const move=(l,t)=>{const b=$('#outfit-board');el.style.left=Math.max(0,Math.min(b.clientWidth-el.offsetWidth,l))+'px';el.style.top=Math.max(0,Math.min(b.clientHeight-el.offsetHeight,t))+'px'};el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture(e.pointerId);const b=$('#outfit-board'),scale=b.getBoundingClientRect().width/b.offsetWidth,x=e.clientX,y=e.clientY,l=el.offsetLeft,t=el.offsetTop;const onmove=ev=>move(l+(ev.clientX-x)/scale,t+(ev.clientY-y)/scale);const end=()=>{el.removeEventListener('pointermove',onmove);save()};el.addEventListener('pointermove',onmove);el.addEventListener('pointerup',end,{once:true});el.addEventListener('pointercancel',end,{once:true})});el.addEventListener('keydown',e=>{const d={ArrowLeft:[-6,0],ArrowRight:[6,0],ArrowUp:[0,-6],ArrowDown:[0,6]}[e.key];if(d){e.preventDefault();move(el.offsetLeft+d[0],el.offsetTop+d[1]);save()}})})}
function toneText(friend,gentle,concise){return state.settings.tone==='gentle'?gentle:state.settings.tone==='concise'?concise:friend}
function stockFor(id){const p=product(id);return state.inventory.filter(i=>i.remaining!==0&&(id==='tee'?['shirt','sweater'].includes(i.type):i.type===p.type))}
function introChat(id){const p=product(id),s=stockFor(id)[0];return toneText(`${id==='wash'&&s?'Your bathroom called. It’s not running a body-wash adoption center.':id==='tee'&&s?'Your oatmeal sweater just spotted its long-lost twin.':'Okay, excellent taste. Let’s add a little context.'}\n\n${s?`You’ve logged ${s.name}${s.remaining>=0&&s.room!=='closet'?`, about ${s.remaining}% left`:''}. `:''}What’s the mission: refill, a new experience, a gift, or simply “I want it”?`,`${s?`You already have ${s.name}. `:''}It’s okay to want something new. What would you like ${p.name} to do for you?`,`Item: ${p.name}. ${s?`Existing stock: ${s.name}, ${s.remaining<0?'amount unknown':s.remaining+'% left'}.`:'No matching stock recorded.'}\nConfirm purpose: refill, try something new, gift, or preference.`)}
function openChat(id='wash',fresh=false){closeSheet();$('#nudge').hidden=true;$('#buddy-fab').hidden=true;if(id!==chatProduct||!messages.length||fresh){cancelMomo();chatProduct=id;messages=[{role:'assistant',text:introChat(id),mode:'welcome',choices:['Restocking','Just want the scent','A gift','I just like it']}]}$('#chat').hidden=false;renderChat();$('#app').inert=true;$('#nav').inert=true;$('#chat-input').focus({preventScroll:true})}
function chatTools(){const last=[...messages].reverse().find(m=>m.role==='assistant'&&m.mode!=='welcome');if(!last)return '';const t=last.text||'',p=product(chatProduct),out=[];if(p.miniVolume&&/mini|smaller|travel|sample|trial/i.test(t))out.push(`<button data-action="compare-mini" data-id="${chatProduct}">Compare the ${p.miniVolume} ml mini ↗</button>`);if(/shelf|backup|left|stock|already|record/i.test(t))out.push('<button data-action="chat-stock">See my shelf ↗</button>');if(/price|\$|deal|cost|cheaper|store/i.test(t))out.push(`<button data-action="compare" data-id="${chatProduct}">Compare prices ↗</button>`);return out.length?`<div class="chat-tools">${out.join('')}</div>`:''}
function renderChat(){$('#chat').innerHTML=`<header class="chat-header"><button class="icon-btn" data-action="close-chat" aria-label="Back">${icon('back')}</button><span class="chat-avatar">${cat()}</span><div><strong>Momo</strong><small>Your taste. My two cents.</small></div><button class="icon-btn" data-action="chat-reset" aria-label="Restart conversation">↻</button></header><div class="chat-context">${art(product(chatProduct))}<span>${product(chatProduct).name}</span><button data-action="compare" data-id="${chatProduct}">Compare ↗</button></div><div class="chat-messages" id="chat-messages"><p class="chat-disclaimer">GEMINI CHAT · SAMPLE SHOPPING DATA</p><p class="chat-privacy">Messages and relevant shelf records go to Google to reply. Photos stay here. Free-tier data may be used to improve Google’s products. Avoid private details.</p>${messages.map(m=>`<div class="message ${m.role}"><span class="eyebrow">${m.role==='user'?'YOU':m.mode==='live'?'MOMO · GEMINI':m.mode==='calculated'?'MOMO · PRICE CALCULATOR':m.mode==='demo'?'MOMO · SCRIPTED DEMO':'MOMO · WELCOME'}</span><div class="bubble">${esc(m.text)}</div>${m.choices?`<div class="chat-choices">${m.choices.map(t=>`<button data-action="chat-choice" data-id="${esc(t)}">${t}</button>`).join('')}</div>`:''}${m.action?`<button class="chat-action" data-action="${m.action}" data-id="${chatProduct}">${m.label} ↗</button>`:''}</div>`).join('')}${chatPending?'<p class="momo-thinking" role="status">Momo is thinking<span>…</span></p>':''}${chatFailure?`<div class="chat-error" role="alert"><p>${esc(chatFailure)}</p><button data-action="chat-retry">Try Gemini again</button><button data-action="chat-demo">Use scripted demo</button></div>`:''}${chatTools()}</div><form id="chat-form"><input id="chat-input" aria-label="Message Momo" placeholder="Okay, hear me out…" autocomplete="off" maxlength="1500" ${chatPending?'disabled':''}><button type="submit" aria-label="Send message" ${chatPending?'disabled':''}>${icon('send')}</button></form>`;$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight}
let chatPending=false,chatFailure='',chatController=null,chatRequest=0,lastChatText='';
function cancelMomo(){chatRequest++;chatController?.abort();chatController=null;chatPending=false;chatFailure=''}
function momoContext(){return {productId:chatProduct,settings:{tone:state.settings.tone,budget:state.settings.budget,member:state.settings.member},wish:state.wish.map(w=>w.id),inventory:state.inventory.map(i=>({id:i.id,name:i.name,type:i.type,room:i.room,remaining:i.remaining,volume:i.volume,date:i.date}))}}
async function respond(text,retry=false){
 text=String(text||'').trim().slice(0,1500);if(!text||chatPending)return;
 if(!retry)messages.push({role:'user',text});
 lastChatText=text;chatPending=true;chatFailure='';const ticket=++chatRequest;
 chatController=new AbortController();const timer=setTimeout(()=>chatController?.abort(),27000);
 const history=messages.slice(0,-1).filter(m=>m.role==='user'||m.mode==='live'||m.mode==='calculated').slice(-10).map(({role,text})=>({role,text}));
 renderChat();
 try{
  const response=await fetch('api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...momoContext(),message:text,history}),signal:chatController.signal});
  let data;try{data=await response.json()}catch{throw new Error('Live chat is unavailable on this host. Open the Vercel app, or choose the labeled demo.')}
  if(!response.ok)throw new Error(data.message||'Momo could not connect. Please try again.');
  if(!['live','calculated'].includes(data.mode)||typeof data.text!=='string'||!data.text.trim())throw new Error('Momo did not receive a reply. Please try again.');
  if(ticket!==chatRequest)return;
  messages.push({role:'assistant',text:data.text,mode:data.mode,model:data.model,systemVersion:data.systemVersion,retrievedIds:data.retrievedIds});
 }catch(error){if(ticket===chatRequest)chatFailure=error.name==='AbortError'?'Momo’s connection took too long. Please try again.':error.message}
 finally{clearTimeout(timer);if(ticket===chatRequest){chatPending=false;chatController=null;renderChat();if(!$('#chat').hidden)$('#chat-input').focus({preventScroll:true})}}
}
function demoReply(){if(chatPending||!chatFailure)return;chatFailure='';if(messages.at(-1)?.role==='user')messages.pop();scriptedRespond(lastChatText)}
function scriptedRespond(text){text=text.trim();if(!text)return;messages.push({role:'user',text});const t=text.toLowerCase(),p=product(chatProduct),s=stockFor(chatProduct)[0];let reply,reason='';if(/quiet|stop|no more|shut up/.test(t)){state.settings.frequency='quiet';reply={text:'Got it. I’ll keep my two cents in my pocket until you ask.'}}
else if(/scent|smell|try|new|curious/.test(t)){reason='Try a new scent';reply={text:p.room==='closet'?'New vibe, understood. Let’s style it with what you have before adding more.':toneText('Ah. Not a soap emergency. A scent crush.\n\nValid. Let’s date the travel size before we move the full bottle in. Less upfront spending; possibly a higher price per ml.','A new scent sounds lovely. A smaller size could let you try it with less upfront spending. We can compare both sizes.','Goal: try a new scent. Compare mini size for lower total spending; check unit price separately.'),action:p.room==='closet'?'outfit':'compare-mini',label:p.room==='closet'?'Try a look':`Compare the ${p.miniVolume} ml mini`}}
else if(/gift|present/.test(t)){reason='A gift';reply={text:'Plot twist: it’s not for your shelf. Your own stock isn’t the deciding factor, then.\n\nWhat’s their taste, and what’s your gift budget?',choices:['Budget: $30','Budget: $50'],action:'compare',label:'Compare full size'}}
else if(/empty|used up|finished|ran out/.test(t)){reason='Restocking';reply={text:'Thanks for the update. The shelf record needs a refresh. Mark the old bottle finished, then we’ll compare a refill.',action:'chat-stock',label:'Update my inventory'}}
else if(/restock|refill|need/.test(t)){reason='Restocking';reply={text:s?`Refill mission accepted. Your record says ${s.name} ${s.remaining<0?'has an unknown amount left':`is about ${s.remaining}% full`}. Is that still accurate?\n\nA sale countdown is not an inventory count.`:'No matching stock recorded. Let’s compare the total cost of a refill.',choices:['It’s finished','Still accurate — compare'],action:'compare',label:'Compare full size'}}
else if(/like|want|love|treat|deserve/.test(t)){reason='I just like it';reply={text:toneText('“I like it” is a reason. We don’t need a courtroom defense.\n\nLet’s just make sure your budget likes it back.','Enjoying it is a valid reason. We can check your budget and the price, and the choice stays yours.','Purpose: personal preference. Next: compare cost against your budget.'),action:'compare',label:'Check the price',choices:['Check my budget','Show my room']}}
else if(/budget|\$|expensive|afford|save money/.test(t)){const total=wishTotal();reply={text:`Your budget: ${money(state.settings.budget)}. Wishlist item total: ${money(total)} before shipping and tax.\n\n${total>state.settings.budget?`That’s ${money(total-state.settings.budget)} over. Want to leave some things as maybes?`:`There’s ${money(state.settings.budget-total)} left. Unspent money is also a nice thing to own.`}`,action:'nav-wish',label:'Review my maybe bag'}}
else if(/outfit|clothes|style|fit/.test(t)){reply={text:'Let’s give the wardrobe a chance to show off. Try the knit and shirt on your style board, or arrange your own flat lay.',action:'outfit',label:'Open outfit studio'}}
else if(/room|stock|shelf|bathroom|inventory/.test(t)){reply={text:'Let’s check what you’ve actually logged. I can remember a record; only you can confirm what’s really left.',action:'chat-stock',label:'See my room'}}
else if(/price|deal|compare|cheap|cost/.test(t)){reply={text:'Five stores, one comparison. Item price plus shipping; tax and membership conditions stay visible.\n\nThese are demo offers, not live deals.',action:'compare',label:'Compare five stores'}}
else reply={text:'Tell me which way you’re leaning. This demo follows a few shopping situations: restocking, trying a new scent, gifting, outfits, or budgeting.',choices:['Restocking','Just want the scent','A gift','Check my budget']};
if(reason){const w=state.wish.find(w=>w.id===chatProduct);if(w)w.reason=reason}persist();messages.push({role:'assistant',...reply,mode:'demo'});renderChat()}
const stories=[['Start at home. Tap a bottle and see what you already own.','Next: meet the new crush'],['Save the almond body wash. Momo has a small shelf-related question.','Next: hear Momo out'],['Tell Momo “Just want the scent”. The reason changes the suggestion.','Next: compare the mini size'],['Five stores. Try member perks, expand a price, and save your preferred plan.','Next: your maybe bag'],['A plan, not a purchase. Your budget and reason travel with the item.','Next: shop your wardrobe'],['Switch pieces on your style board, or drag a flat lay. Save your favorite look.','Finish the tour']];
const storyTitles=['Shelf check','A new crush','Momo asks why','Compare five stores','Plans, not purchases','Shop your closet'];
function updateStory(){$('#story-steps').innerHTML=storyTitles.map((t,i)=>`<li class="${i===story?'now':i<story?'done':''}"><button data-story="${i}"><b>0${i+1}</b><span>${t}</span></button></li>`).join('');$('#story-copy').textContent=story<0?'A scent crush, a shelf check, and a smarter little treat. Six taps, about a minute.':stories[story][0];$('#story-btn').innerHTML=story<0?'Try the little story <span>↗</span>':story>=5?'Back to the start <span>↺</span>':stories[story][1].replace('Next: ','Next · ')+' <span>→</span>'}
function goStory(i){if(i<0||i>5){story=-1;navigate('home');updateStory();return}story=i;if(i>=2&&!wishHas('wash')){state.wish.push({id:'wash',reason:''});persist()}if(i===0){room='bath';ghost=null;navigate('home')}if(i===1){navigate('shop');detail('wash')}if(i===2)openChat('wash',true);if(i===3)compare('wash','mini');if(i===4)navigate('wish');if(i===5){room='closet';navigate('home');outfitView()}updateStory()}
function nextStory(){goStory(story+1)}
function resetConfirm(){showSheet('<h2>A fresh start?</h2><p>This clears this browser’s wishlist, selected photos, plans, outfits and settings, then restores the sample rooms.</p><div class="action-row"><button class="secondary" data-action="close-sheet">Keep my things</button><button class="primary" data-action="reset">Reset demo</button></div>','Reset demo')}
function reset(){cancelMomo();state=blankState();persist();room='bath';story=-1;ghost=null;messages=[];query='';category='All';compId='wash';size='full';addCount=0;lastNudge=0;outfit={top:'o8',bottom:'o9',shoes:'o10',bag:'bag'};outfitPositions={};navigate('home');toast('Fresh shelves. Same good taste.')}
function purchased(id){const p=product(id),plan=state.plans.filter(x=>x.id===id).at(-1);showSheet(`<span class="eyebrow">A REAL-LIFE UPDATE</span><h2>Already brought it home?</h2><p>Move ${p.name} · ${sizeLabel(p,plan?.size||'full')} from your wishlist to your ${roomName(p.room).toLowerCase()}.</p><p class="footnote">This only updates your record. It won’t place an order.</p><div class="action-row"><button class="secondary" data-action="close-sheet">Not yet</button><button class="primary" data-action="confirm-purchase" data-id="${id}">Yes, I own it</button></div>`,'Mark as owned')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;switch(b.dataset.action){
case 'nav':navigate(id);break;case 'room':{const a=rooms.findIndex(r=>r[0]===room),z=rooms.findIndex(r=>r[0]===id);if(a!==z){roomDir=z>a?1:-1;room=id;render(false)}break}case 'room-prev':changeRoom(-1);break;case 'room-next':changeRoom(1);break;case 'category':category=id;render(false);break;case 'product':detail(id);break;case 'settings':settings();break;case 'close-sheet':closeSheet();break;
case 'wish-toggle':{const from=!wishHas(id)&&(b.closest('.product-card')?.querySelector('.product-picture')||b).getBoundingClientRect();toggleWish(id);if(from)flyToBag(id,from);break}case 'detail-wish':{const from=!wishHas(id)&&$('.detail-art')?.getBoundingClientRect();toggleWish(id,true);closeSheet();if(from)flyToBag(id,from);break}case 'compare':compare(id);break;case 'compare-mini':compare(id,'mini');break;case 'size':size=id;render(false);break;case 'member':state.settings.member=!state.settings.member;persist();render(false);break;case 'store':expandedStore=expandedStore===id?'':id;render(false);break;case 'save-best':saveOffer(offers()[0].index);break;case 'save-store':saveOffer(id);break;case 'pick-product':showSheet('<h2>What are we comparing?</h2><div class="sample-grid">'+products.map(p=>`<button class="sample-card" data-action="compare" data-id="${p.id}">${art(p)}<span>${p.name}</span></button>`).join('')+'</div>','Choose comparison item');break;
case 'inventory':inventoryDetail(id);break;case 'inventory-list':inventoryList();break;case 'preview':ghost=id;room=product(id).room;navigate('home');toast('Preview only. It’s not in your inventory.');break;case 'clear-ghost':ghost=null;render(false);toast('Still on your wishlist. No rush.');break;case 'ghost':render(false);break;case 'remaining-save':owned(id).remaining=Number($('#remaining-range').value);persist();closeSheet();render(false);toast('Shelf knowledge updated.');break;case 'used-up':owned(id).remaining=0;persist();closeSheet();render(false);toast('Finished. A little room to breathe.');break;case 'move-item':room=$('#move-room').value;owned(id).room=room;persist();navigate('home');toast('Moved in.');break;
case 'tone':state.settings.tone=id;persist();settings();break;case 'frequency':state.settings.frequency=id;persist();settings();break;case 'budget-save':{const v=Number($('#budget-field').value);if(!Number.isFinite(v)||v<1||v>100000){toast('Choose a budget between $1 and $100,000.');break}state.settings.budget=v;persist();render(false);toast('Budget saved. Your rules.');break}
case 'album':album();break;case 'upload':$('#photo-file').click();break;case 'sample-select':selection.has(id)?selection.delete(id):selection.add(id);b.classList.toggle('selected',selection.has(id));b.setAttribute('aria-pressed',String(selection.has(id)));$('#album-next').disabled=!selection.size;$('#album-next').textContent=selection.size?`Confirm ${selection.size} item${selection.size>1?'s':''} →`:'Choose an item to continue';break;case 'album-next':confirmAlbum();break;case 'album-save':saveAlbum();break;
case 'outfit':{closeChat();if(id&&owned(id)?.room==='closet'){const p=owned(id);outfit[p.type==='pants'?'bottom':p.type==='shoes'?'shoes':p.type==='bag'?'bag':'top']=id}else if(id==='tee'||id==='bag')outfit[id==='tee'?'top':'bag']=id;else if(state.outfits.length){const last=state.outfits.at(-1);outfit={...last.pieces};outfitPositions={...(last.positions||{})}}outfitView();break}case 'outfit-mode':outfitMode=id;outfitView();break;case 'outfit-pick':{const p=outfitArt(id);outfit[p.type==='pants'?'bottom':p.type==='shoes'?'shoes':p.type==='bag'?'bag':'top']=id;outfitView();break}case 'outfit-save':state.outfits.push({pieces:{...outfit},positions:{...outfitPositions},savedAt:new Date().toISOString()});persist();toast('Look saved to your wishlist.');break;
case 'chat':openChat(id||chatProduct);break;case 'close-chat':closeChat();break;case 'chat-retry':respond(lastChatText,true);break;case 'chat-demo':demoReply();break;case 'chat-reset':openChat(chatProduct,true);break;case 'chat-choice':respond(id);break;case 'chat-stock':room=product(chatProduct).room;navigate('home');break;case 'nav-wish':navigate('wish');break;case 'close-nudge':$('#nudge').hidden=true;break;
case 'delete-plan':state.plans.splice(Number(id),1);persist();render(false);break;case 'plan-compare':{const p=state.plans[Number(id)];state.settings.member=p.member;compare(p.id,p.size);break}case 'purchased':purchased(id);break;case 'confirm-purchase':{const p=product(id),plan=state.plans.filter(x=>x.id===id).at(-1);state.inventory.push({...p,id:'purchased-'+Date.now(),volume:plan?.size==='mini'?p.miniVolume:p.volume,remaining:100,date:new Date().toISOString().slice(0,10)});state.wish=state.wish.filter(w=>w.id!==id);state.plans=state.plans.filter(w=>w.id!==id);ghost=null;room=p.room;persist();navigate('home');toast('Added to your room. No payment made.');break}
case 'reset-confirm':resetConfirm();break;case 'reset':reset();break;case 'story':nextStory();break;
}});
$('#story-btn').onclick=nextStory;$('#reset-desktop').onclick=resetConfirm;$('#buddy-fab').onclick=()=>openChat(momoTarget());$('#desktop-character').innerHTML='<img src="assets/artwork/girl-cream.webp" alt="" class="night-character">';document.addEventListener('click',e=>{const st=e.target.closest('[data-story]');if(st)goStory(Number(st.dataset.story))});
let dockTimer;$('#app').addEventListener('scroll',()=>{const f=$('#buddy-fab');f.classList.add('docked');clearTimeout(dockTimer);dockTimer=setTimeout(()=>f.classList.remove('docked'),900)},{passive:true});
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))closeSheet()});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render(false);$('#search').focus();$('#search').setSelectionRange(pos,pos)}if(e.target.id==='remaining-range')$('#remaining-value').textContent=e.target.value+'%'});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();respond($('#chat-input').value)}});
document.addEventListener('change',e=>{if(e.target.id!=='photo-file')return;const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Choose an image file.');return}if(file.size>10*1024*1024){toast('Choose a photo under 10 MB.');return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas'),scale=Math.min(1,700/img.width,700/img.height);canvas.width=img.width*scale;canvas.height=img.height*scale;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);photoDraft=canvas.toDataURL('image/jpeg',.78);confirmAlbum()};img.onerror=()=>toast('Couldn’t read that image. Try a JPG or PNG.');img.src=reader.result};reader.readAsDataURL(file)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#overlay').hidden)closeSheet();else if(!$('#chat').hidden)closeChat();else if(!$('#nudge').hidden)$('#nudge').hidden=true;else if(document.body.classList.contains('present'))togglePresent(false)}if(e.key==='Tab'){const layer=!$('#overlay').hidden?$('#overlay'):!$('#chat').hidden?$('#chat'):null;if(layer){const nodes=[...layer.querySelectorAll('button,input,select,summary,[tabindex="0"]')].filter(el=>!el.disabled&&el.offsetParent!==null);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}});
render();

function fitPhone(){const compact=window.innerWidth<=760,present=document.body.classList.contains('present');const scale=compact?1:present?Math.min(1.3,Math.max(.5,(window.innerHeight-48)/874)):Math.min(1,Math.max(.48,(window.innerHeight-170)/874));document.documentElement.style.setProperty('--phone-scale',scale);}
window.addEventListener('resize',fitPhone);fitPhone();


function togglePresent(on=!document.body.classList.contains('present')){document.body.classList.toggle('present',on);$('#present-btn').textContent=on?'Exit present ✕':'Present ▶';fitPhone()}
$('#present-btn').onclick=()=>togglePresent();
$('.wordmark').onclick=e=>{e.preventDefault();navigate('home')};
